def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: ISO 8601 duration string representation of the timedelta
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError("value must be a datetime.timedelta instance")
    total_seconds = value.total_seconds()
    sign = '-' if total_seconds < 0 else ''
    total_seconds = abs(total_seconds)
    days = int(total_seconds // 86400)
    total_seconds -= days * 86400
    hours = int(total_seconds // 3600)
    total_seconds -= hours * 3600
    minutes = int(total_seconds // 60)
    total_seconds -= minutes * 60
    seconds = total_seconds
    # Format seconds with up to 6 decimal places, trimming trailing zeros
    if seconds.is_integer():
        sec_str = f"{int(seconds)}"
    else:
        sec_str = f"{seconds:.6f}".rstrip('0').rstrip('.')
    parts = []
    if days:
        parts.append(f"{days}D")
    time_parts = []
    if hours:
        time_parts.append(f"{hours}H")
    if minutes:
        time_parts.append(f"{minutes}M")
    if sec_str:
        time_parts.append(f"{sec_str}S")
    if time_parts:
        parts.append("T" + "".join(time_parts))
    if not parts:
        parts.append("0S")
    return sign + "P" + "".join(parts)

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: Time object
    :type value: datetime.time
    :return: ISO formatted string or None
    """
    if value is None:
        return None
    try:
        import datetime
        if not isinstance(value, datetime.time):
            raise TypeError(f"Expected datetime.time instance, got {type(value).__name__}")
        return value.isoformat()
    except Exception as e:
        raise ValueError(f"Error dehydrating time value: {e}") from e

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated record attribute if present
        if hasattr(self, "record") and isinstance(self.record, dict):
            return list(self.record.keys())
        # Fallback to a generic data attribute
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())
        # If the instance itself behaves like a dict, use the built‑in method
        if isinstance(self, dict):
            return list(dict.keys(self))
        # As a last resort, expose the instance's own attributes
        return list(self.__dict__.keys())
    except Exception as exc:
        raise RuntimeError("Unable to retrieve keys from the record") from exc

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(handlers)
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine if the instance behaves like a mapping or a sequence
    if hasattr(self, "items"):  # mapping-like
        container = self
        is_dict = True
    elif hasattr(self, "__iter__"):  # sequence-like
        container = list(self)
        is_dict = False
    else:
        raise TypeError("values() requires a mapping or sequence-like object")

    # If no keys are supplied, return all values
    if not keys:
        return list(container.values()) if is_dict else container

    result = []
    for key in keys:
        try:
            if is_dict:
                # For mappings, use the key directly
                if key in container:
                    result.append(container[key])
            else:
                # For sequences, only integer indices are valid
                if isinstance(key, int):
                    if -len(container) <= key < len(container):
                        result.append(container[key])
        except Exception:
            # Skip any key that causes an error (e.g., out-of-range, unhashable)
            continue
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine underlying mapping
    if isinstance(self, dict):
        mapping = self
    elif hasattr(self, 'items') and callable(self.items):
        mapping = dict(self.items())
    else:
        mapping = {k: v for k, v in self.__dict__.items() if not k.startswith('_')}

    if not keys:
        return mapping

    result = {}
    for k in keys:
        if isinstance(k, int):
            try:
                key = list(mapping.keys())[k]
            except IndexError:
                raise IndexError(f"Index {k} out of bounds")
            result[key] = mapping[key]
        else:
            result[k] = mapping.get(k, None)
    return result

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Retrieve the data attribute safely
    try:
        data = getattr(self, "data")
    except AttributeError:
        raise AttributeError("The object does not have a 'data' attribute")

    # Ensure the data is a bytes-like object
    if not isinstance(data, (bytes, bytearray, list)):
        raise TypeError("'data' must be a bytes-like object (bytes, bytearray, or list of ints)")

    # Check that there are at least two bytes to pop
    if len(data) < 2:
        raise ValueError("Not enough data to pop a 16‑bit value (requires at least 2 bytes)")

    # Extract the last two bytes
    try:
        b1 = data[-2]
        b2 = data[-1]
    except Exception as exc:
        raise ValueError("Failed to index the last two bytes of data") from exc

    # Remove the last two bytes from the data container
    if isinstance(data, bytearray):
        del data[-2:]
    else:
        # For immutable types (bytes, list), reassign a sliced copy
        self.data = data[:-2]

    # Convert the two bytes to a big‑endian unsigned integer
    return (b1 << 8) | b2

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate that seq is a Sequence
    try:
        from collections.abc import Sequence as _Seq
    except Exception as exc:
        raise RuntimeError("collections.abc.Sequence is not available") from exc

    if not isinstance(seq, _Seq):
        raise TypeError(f"_shuffled expects a Sequence[str], got {type(seq).__name__}")

    # Ensure all elements are strings
    for idx, item in enumerate(seq):
        if not isinstance(item, str):
            raise ValueError(f"Element at index {idx} is not a string: {item!r}")

    # Empty sequence is a no‑op
    if not seq:
        return []

    # Create a deterministic seed from the content of the sequence
    try:
        import hashlib
    except Exception as exc:
        raise RuntimeError("hashlib module is required for deterministic shuffling") from exc

    # Join elements with a null byte to avoid accidental collisions
    joined = "\0".join(seq)
    seed = int(hashlib.sha256(joined.encode("utf-8")).hexdigest(), 16)

    # Perform the shuffle using a Random instance seeded deterministically
    try:
        import random
    except Exception as exc:
        raise RuntimeError("random module is required for shuffling") from exc

    shuffled = list(seq)
    rnd = random.Random(seed)
    rnd.shuffle(shuffled)
    return shuffled

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    # Validate cache
    if not hasattr(cache, "__getitem__") or not hasattr(cache, "__setitem__"):
        raise TypeError("cache must be a dict-like object supporting __getitem__ and __setitem__")
    # Resolve key function
    if key is None:
        def default_hashkey(*args, **kwargs):
            # Simple hashable representation of args and kwargs
            return (args, tuple(sorted(kwargs.items())))
        key_func = default_hashkey
    elif callable(key):
        key_func = key
    else:
        raise TypeError("key must be a callable or None")
    # Validate lock if provided
    if lock is not None:
        if not hasattr(lock, "acquire") or not hasattr(lock, "release"):
            raise TypeError("lock must have acquire() and release() methods")
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key_func(*args, **kwargs)
            except Exception as exc:
                raise RuntimeError("Key function raised an exception") from exc
            # Use lock if provided
            if lock is not None:
                lock.acquire()
                try:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
                finally:
                    lock.release()
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Basic validation of parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}
        order = []

        def _make_key(args, kwargs, typed):
            """Create a hashable key from args and kwargs."""
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                key = tuple((arg, type(arg)) for arg in key)
            try:
                hash(key)
            except TypeError:
                raise TypeError("unhashable type in arguments")
            return key

        def wrapper(*args, **kwargs):
            try:
                key = _make_key(args, kwargs, typed)
            except TypeError as exc:
                raise TypeError(f"Cannot cache function {func.__name__} with unhashable arguments") from exc

            now = timer()
            if key in cache:
                result, timestamp = cache[key]
                if now - timestamp < ttl:
                    # Move key to the end to mark it as recently used
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return result
                else:
                    # Expired entry
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass

            # Compute new result
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise

            # Store in cache
            cache[key] = (result, now)
            order.append(key)

            # Enforce maxsize
            if len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)

            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__wrapped__ = func
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorating_function(user_function):
        from collections import OrderedDict
        cache = OrderedDict()
        hits = misses = 0

        def make_key(args, kwargs):
            # Build a hashable key from args and kwargs
            key = args
            if kwargs:
                # Sort kwargs to ensure deterministic order
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                # Include the type of each argument in the key
                key = tuple((arg, type(arg)) for arg in key)
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            try:
                key = make_key(args, kwargs)
            except TypeError:
                # Unhashable arguments; bypass cache
                return user_function(*args, **kwargs)

            if key in cache:
                hits += 1
                result = cache.pop(key)
                cache[key] = result  # mark as most recently used
                return result
            else:
                misses += 1
                result = user_function(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)  # remove least recently used
                return result

        def cache_info():
            """Report cache statistics"""
            return {
                'hits': hits,
                'misses': misses,
                'maxsize': maxsize,
                'currsize': len(cache)
            }

        def cache_clear():
            """Clear the cache and statistics"""
            nonlocal hits, misses
            cache.clear

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = next(iter(self.items()))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    del self[key]
    return key, value

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    try:
        if key in self:
            return self[key]
        else:
            self[key] = default
            return default
    except Exception as exc:
        # Re-raise with a more informative message
        raise ValueError(f"Error setting default for key {key!r}: {exc}") from exc

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        if key in self:
            return self[key]
        return default
    except Exception as exc:
        raise TypeError(f"Failed to retrieve key {key!r}: {exc}") from exc

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise ValueError("cache must not be None")
    if key is None:
        raise ValueError("key function must not be None")

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                # If key function fails, propagate the exception
                raise RuntimeError("Key function raised an exception") from exc

            # Acquire lock if provided
            if lock is not None:
                try:
                    lock.acquire()
                except Exception as exc:
                    raise RuntimeError("Failed to acquire lock") from exc

            try:
                if k in cache:
                    return cache[k]
                # Compute result
                result = func(*args, **kwargs)
                # Store in cache
                try:
                    cache[k] = result
                except Exception as exc:
                    # If cache assignment fails, ignore caching
                    raise RuntimeError("Failed to store result in cache") from exc
                return result
            finally:
                if lock is not None:
                    try:
                        lock.release()
                    except Exception:
                        # Ignore lock release errors
                        pass

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

@staticmethod
def is_file_exist(file_name):
    """Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    try:
        if not isinstance(file_name, str):
            return False
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def _getTargetClass(self):
    """Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix."""
    name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise ValueError("object cannot be None")
    try:
        return zope.interface.directlyProvidedBy(object)
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve directly provided interfaces for {object!r}") from exc

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Validate the `all` argument
    if not isinstance(all, bool):
        raise TypeError(f"'all' must be a bool, got {type(all).__name__}")

    try:
        interface = {}
        # If `all` is True, include attributes from all base classes
        classes = (self.__class__,) + (self.__class__.mro()[1:] if all else ())
        for cls in classes:
            # Many frameworks expose an interface dictionary as a class attribute
            if hasattr(cls, "__interface__"):
                iface = getattr(cls, "__interface__")
                if isinstance(iface, dict):
                    interface.update(iface)
                else:
                    # If the interface is not a dict, skip it but log a warning
                    import warnings
                    warnings.warn(
                        f"Interface of {cls.__name__} is not a dict; skipping",
                        RuntimeWarning,
                    )
        return interface
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError to avoid leaking internal details
        raise RuntimeError(
            f"Failed to retrieve interface names and descriptions for {self.__class__.__name__}"
        ) from exc

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect

    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean")

    cls = self.__class__

    if all:
        # Include attributes from the class and all base classes
        attrs = [
            name
            for name, value in inspect.getmembers(
                cls, lambda a: not inspect.isroutine(a)
            )
            if not name.startswith("_")
        ]
    else:
        # Only attributes defined directly on this class
        attrs = [
            name
            for name, value in cls.__dict__.items()
            if not inspect.isroutine(value) and not name.startswith("_")
        ]

    return attrs

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError("output must be a list or None")

    # Handle None sequence
    if sequence is None:
        return output

    # Ensure sequence is iterable
    try:
        iter(sequence)
    except TypeError:
        raise TypeError("sequence must be an iterable")

    for item in sequence:
        if item is None:
            continue
        # Expand tuples, lists, and sets
        if isinstance(item, (tuple, list, set)):
            output.extend(item)
        else:
            output.append(item)

    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
    except NameError as e:
        raise NameError("The function `_c_optimizations_required` is not defined.") from e
    except Exception as e:
        raise RuntimeError("Error evaluating `_c_optimizations_required`") from e

    if not isinstance(required, bool):
        raise TypeError("Expected `_c_optimizations_required` to return a bool, got %r" % type(required))
    return not required

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value was provided during construction, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the existing bin structure if it exists
            if hasattr(self, "bins"):
                if isinstance(self.bins, dict):
                    for key in self.bins:
                        self.bins[key] = self.initial_value
                else:
                    # Assume an iterable of bins
                    self.bins = [self.initial_value for _ in self.bins]
            else:
                # No bins yet – create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # No explicit initial value – create bins via the factory method
            self.bins = self.make_bins()
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        # Validate separator
        if not isinstance(separator, str):
            raise TypeError("separator must be a string")
        # Validate header
        if header is not None and not isinstance(header, str):
            raise TypeError("header must be a string or None")

        lines = []

        # If a header is provided, add it first
        if header is not None:
            lines.append(header)

        # Helper to convert a value to a CSV-safe string
        def _to_str(val):
            try:
                return str(val)
            except Exception:
                return ""

        # Iterate over graph points
        try:
            points_iter = getattr(self, "points", None)
            if points_iter is None:
                # Try to use an iterator method
                points_iter = iter(self)
        except Exception:
            raise ValueError("Object does not provide points for CSV conversion")

        for point in points_iter:
            # Expect point to be a tuple (coord, value)
            if not isinstance(point, (list, tuple)) or len(point) != 2:
                continue  # skip malformed entries
            coord, value = point

            # Convert coordinate
            if isinstance(coord, (list, tuple)):
                coord_str = separator.join(_to_str(c) for c in coord)
            else:
                coord_str = _to_str(coord)

            # Convert value
            if isinstance(value, (list, tuple)) and not isinstance(value, (str, bytes)):
                value_str = separator.join(_to_str(v) for v in value)
            else:
                value_str = _to_str(value)

            # Combine coordinate and value parts
            line = separator.join([coord_str, value_str]) if value_str else coord_str
            lines.append(line)

        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    try:
        # Prefer a dictionary mapping coordinate names to index lists
        errors = getattr(self, "errors", None)
        if isinstance(errors, dict):
            return list(errors.get(coord_name, []))

        # Fallback: assume a list of (index, coord) tuples
        if isinstance(errors, (list, tuple)):
            return [idx for idx, c in errors if c == coord_name]

        # If no recognizable structure, return empty list
        return []

    except Exception as exc:
        raise RuntimeError(
            f"Unable to retrieve error indices for coordinate '{coord_name}'"
        ) from exc

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    if bins is None or edges is None:
        raise ValueError("bins and edges must not be None")
    try:
        bin_list = list(bins)
        edge_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    if len(edge_list) != len(bin_list) + 1:
        raise ValueError("edges length must be one more than bins length")

    if not edge_list:
        return 0.0

    # Ensure edges are monotonically increasing
    for i in range(len(edge_list) - 1):
        if edge_list[i+1] <= edge_list[i]:
            raise ValueError("edges must be strictly increasing")

    # Compute widths and integral
    total = 0.0
    for b, e_start, e_end in zip(bin_list, edge_list[:-1], edge_list[1:]):
        try:
            width = float(e_end) - float(e_start)
            value = float(b)
        except (TypeError, ValueError):
            raise TypeError("bins and edges must contain numeric values")
        total += value * width

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle None or non-iterable inputs gracefully
    if seq is None:
        return False

    # Avoid treating strings or bytes as iterables of elements
    if isinstance(seq, (str, bytes)):
        return False

    # If seq is a single element, check its type directly
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False

    # Try iterating over seq to find relevant elements
    try:
        has_fill = False
        for item in seq:
            if isinstance(item, Source):
                # Presence of a Source element disqualifies the sequence
                return False
            if isinstance(item, FillRequest):
                has_fill = True
        return has_fill
    except Exception:
        # Any error during iteration means we cannot confirm the sequence
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if not isinstance(weight, (int, float)):
        raise TypeError("weight must be a numeric value")

    # Validate coord
    try:
        coord = list(coord)
    except TypeError:
        raise TypeError("coord must be an iterable of coordinates")

    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object missing 'edges' attribute")
    if not hasattr(self, "data"):
        raise AttributeError("Histogram object missing 'data' attribute")

    if len(coord) != len(self.edges):
        raise ValueError("coord length must match histogram dimensionality")

    # Find bin indices for each dimension
    import bisect
    indices = []
    for dim, (c, edges) in enumerate(zip(coord, self.edges)):
        if not isinstance(edges, (list, tuple)):
            raise TypeError(f"edges[{dim}] must be a list or tuple")
        # Ensure edges are sorted
        if any(edges[i] > edges[i + 1] for i in range(len(edges) - 1)):
            raise ValueError(f"edges[{dim}] must be sorted in ascending order")
        idx = bisect.bisect_right(edges, c) - 1
        # Check bounds: edges define bin boundaries; last edge is upper bound
        if idx < 0 or idx >= len(edges) - 1:
            # Coordinate outside histogram edges; ignore
            return
        indices.append(idx)

    # Increment the appropriate bin
    try:
        # Attempt numpy-like indexing
        self.data[tuple(indices)] += weight
    except Exception:
        # Fallback to nested list indexing
        try:
            d = self.data
            for i in indices[:-1]:
                d = d[i]
            d[indices[-1]] += weight
        except Exception as e:
            raise RuntimeError(f"Failed to increment histogram bin: {e}") from e
    return None

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'labels must be a dict'}])

    # Regular expressions for keys and values (example patterns)
    key_regex = re.compile(r'^[A-Za-z0-9_-]+$')
    value_regex = re.compile(r'^[A-Za-z0-9_-]+$')

    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key pattern
            if not key_regex.match(key):
                messages.append(
                    {key: f"Label key '{key}' does not match the regex {key_regex.pattern}"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            messages.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value pattern
            if not value_regex.match(value):
                messages.append(
                    {value: f"Label value '{value}' does not match the regex {value_regex.pattern}"}
                )

    if messages:
        raise ValidationError(messages)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    # Keys that should be copied verbatim when this is the top-level dictionary
    identifying_fields = {"apiVersion", "kind", "metadata"}

    def _process(value, top=False):
        if isinstance(value, dict):
            out = {}
            for k, v in value.items():
                if top and k in identifying_fields:
                    out[k] = v
                else:
                    out[k] = _process(v, top=False)
            return out
        if isinstance(value, list):
            return [_process(item, top=False) for item in value]
        # Non-dict, non-list values are replaced with None
        return None

    return _process(manifest_dict, top=first_level)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        raise ValueError("The provided app object must have a 'spec.manifest' attribute")

    manifest = app.spec.manifest

    # Ensure the manifest is iterable
    try:
        resources = list(manifest)
    except TypeError:
        raise TypeError("app.spec.manifest must be an iterable of resources")

    created_schemas = []

    for resource in resources:
        # Skip resources that already have a custom observer schema
        if hasattr(resource, "observer_schema") and resource.observer_schema is not None:
            continue

        # Build a very simple default schema
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }

        # Attach the schema to the resource
        try:
            setattr(resource, "observer_schema", default_schema)
        except Exception:
            # If we cannot set the attribute, skip this resource
            continue

        created_schemas.append((resource, default_schema))

    return created_schemas

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        # Resolve path to a string
        if isinstance(path, str):
            path = os.path.abspath(path)
        elif hasattr(path, "path"):  # pyfs root object
            path = os.path.abspath(path.path)
        else:
            return False

        if not os.path.exists(path) or not os.path.isdir(path):
            return False

        # Basic OCFL structure checks
        required_files = [".ocfl_root", ".ocfl_manifest"]
        for fname in required_files:
            if not os.path.isfile(os.path.join(path, fname)):
                return False

        # Validate .ocfl_root content
        try:
            with open(os.path.join(path, ".ocfl_root"), "r", encoding="utf-8") as f:
                content = f.read()
                if "ocfl_version" not in content:
                    return False
        except Exception:
            return False

        # Additional checks can be added here (e.g., manifest format, object directories)

        return True
    except Exception:
        # Any unexpected error results in a validation failure
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        status = getattr(self, 'status', None)
        if status is None:
            return prefix + 'No status available'
        if isinstance(status, (list, tuple)):
            status_text = '; '.join(map(str, status))
        else:
            status_text = str(status)
        return prefix + status_text
    except Exception as e:
        return prefix + f'Error retrieving status: {e}'

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure prefix is a string
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    # Attempt to retrieve the validation log from common attribute names
    log = getattr(self, 'validation_log', None) or getattr(self, 'log', None)

    # If no log is present, return an empty string
    if not log:
        return ''

    # Convert the log to an iterable of entries
    try:
        if isinstance(log, (list, tuple)):
            entries = log
        else:
            entries = list(log)
    except Exception:
        # If the log is not iterable, treat it as a single entry
        entries = [log]

    # Build the string representation, prefixing each entry
    try:
        return '\n'.join(prefix + str(entry) for entry in entries)
    except Exception:
        # In case any entry cannot be converted to string, return an empty string
        return ''

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check for inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine the specification version to use for validation
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Expect a format like "foLiA-1.0" or "spec-2.1"
            parts = type_val.split("-")
            if len(parts) == 2:
                # Use the part after the dash as the version
                spec_version = parts[1]

    # Validate that we have a usable spec_version
    if not isinstance(spec_version, str) or not spec_version:
        raise ValueError("spec_version must be a non-empty string")

    # Example structural checks – these can be extended as needed
    # Inventory must contain an 'items' key that is a list
    items = inventory.get("items")
    if items is None:
        raise ValueError("inventory missing required 'items' key")
    if not isinstance(items, list):
        raise TypeError("'items' must be a list")

    # Validate each item in the list
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"item at index {idx} is not a dictionary")
        # Example required fields for each item
        if "id" not in item:
            raise ValueError(f"item at index {idx} missing required 'id' field")
        if "value" not in item:
            raise ValueError(f"item at index {idx} missing required 'value' field")

    # If all checks pass, return True
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple of digests")

    digests_used_set = set(digests_used)

    # Check that every digest in the manifest is used
    missing_in_use = [
        fname for fname, digest in manifest_files.items()
        if digest not in digests_used_set
    ]
    if missing_in_use:
        raise ValueError(
            f"Digests for files {missing_in_use} are present in the manifest but not used"
        )

    # Check that every used digest is present in the manifest
    used_not_in_manifest = [
        d for d in digests_used_set if d not in manifest_files.values()
    ]
    if used_not_in_manifest:
        raise ValueError(
            f"Used digests {used_not_in_manifest} are not present in the manifest"
        )

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same InventoryValidator class")

    # Ensure required attributes exist on both objects
    required_attrs = ("id", "version", "inventory")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"self missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior missing required attribute '{attr}'")

    # Check that the prior version is older
    if prior.version >= self.version:
        raise ValueError(
            f"prior.version ({prior.version}) must be less than self.version ({self.version})"
        )

    # Check that the identifiers match
    if prior.id != self.id:
        raise ValueError(
            f"prior.id ({prior.id}) does not match self.id ({self.id})"
        )

    # Verify that the prior inventory is a subset of the current inventory
    try:
        prior_keys = set(prior.inventory.keys())
        current_keys = set(self.inventory.keys())
    except Exception as exc:
        raise ValueError(f"Error accessing inventory keys: {exc}")

    if not prior_keys.issubset(current_keys):
        missing = prior_keys - current_keys
        raise ValueError(
            f"prior inventory contains items not present in current inventory: {missing}"
        )

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None:
        return {}
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer")
    try:
        target_version = int(version)
    except ValueError:
        raise ValueError("version must be convertible to an integer")

    result = {}

    # Helper to add entries to result
    def _add_entry(logical_path, content_file):
        if logical_path is None or content_file is None:
            return
        result.setdefault(logical_path, set()).add(content_file)

    # Case 1: inventory is a mapping of version -> list of entries
    if isinstance(inventory, dict):
        for ver_key, entries in inventory.items():
            try:
                ver_num = int(ver_key)
            except (ValueError, TypeError):
                continue
            if ver_num < target_version:
                continue
            if not isinstance(entries, (list, tuple)):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                _add_entry(entry.get("logical_path"), entry.get("content_file"))

    # Case 2: inventory is a list of entries with a 'version' field
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            try:
                ver_num = int(entry.get("version", -1))
            except (ValueError, TypeError):
                continue
            if ver_num < target_version:
                continue
            _add_entry(entry.get("logical_path"), entry.get("content_file"))

    else:
        raise TypeError("inventory must be a dict or a list of entries")

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    # Ensure manifest_files supports membership testing
    if not hasattr(manifest_files, '__contains__'):
        raise ValueError("manifest_files must be a collection supporting membership tests")

    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"file entry at index {idx} is not a dictionary")
        if 'path' not in entry:
            raise ValueError(f"file entry at index {idx} missing required 'path' key")
        if 'hash' not in entry:
            raise ValueError(f"file entry at index {idx} missing required 'hash' key")

        path = entry['path']
        if path in seen_paths:
            raise ValueError(f"duplicate file path '{path}' found in fixity block")
        seen_paths.add(path)

        if path not in manifest_files:
            raise ValueError(f"file path '{path}' referenced in fixity block is not present in the manifest")

    return True

def files_list(path):
    """Return the files in `path`"""
    import os
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string or path-like object")
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except PermissionError as e:
        raise PermissionError(f"Permission denied when accessing {path}") from e
    except Exception as e:
        raise RuntimeError(f"Error listing files in {path}: {e}") from e

def _eval_file(prefix, file_path):
    """Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        full path to the file

    Returns
    -------
    dict
        mapping of prefix to dict with keys 'type' and 'path'
    """
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    # Check that the file exists
    try:
        with open(file_path, 'rb'):
            pass
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path}")
    except OSError as e:
        raise RuntimeError(f"Error accessing file {file_path}: {e}") from e

    try:
        lower_path = file_path.lower()
        if 'asset' in lower_path:
            file_type = 'asset'
        elif 'rendition' in lower_path:
            file_type = 'rendition'
        else:
            raise ValueError(f"Unable to determine package type for file: {file_path}")

        return {prefix: {'type': file_type, 'path': file_path}}
    except Exception as e:
        raise RuntimeError(f"Error evaluating file {file_path}: {e}") from e

def add_asset(self, basename, file_path):
    """Add an asset mapping basename to file_path.

    Parameters:
        basename (str): The asset name (including extension).
        file_path (str): Path to the file on disk.

    Raises:
        TypeError: If basename or file_path is not a string.
        FileNotFoundError: If file_path does not exist.
        ValueError: If basename already exists in assets.
    """
    if not isinstance(basename, str):
        raise TypeError("basename must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    try:
        import os
    except ImportError:
        raise RuntimeError("os module is required to verify file existence")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")
    if not hasattr(self, "assets"):
        self.assets = {}
    if basename in self.assets:
        raise ValueError(f"Asset with basename '{basename}' already exists.")
    self.assets[basename] = file_path
    return None

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        raise ValueError("node cannot be None")
    if not hasattr(node, "xpath"):
        raise TypeError("node must support an xpath() method")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple of XPath strings")

    # Iterate over the provided XPath expressions and return the first match
    for xpath_expr in pubdate_xpaths:
        try:
            matches = node.xpath(xpath_expr)
            if matches:
                return matches[0]
        except Exception:
            # If an XPath evaluation fails, skip to the next expression
            continue

    # No match found
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")
    try:
        lines = []
        prefix = ' ' * indent
        cls_name = self.__class__.__name__
        id_val = getattr(self, 'id', None)
        id_part = f" id={id_val}" if id_val is not None else ""
        attrs = getattr(self, 'attributes', None)
        if isinstance(attrs, dict):
            attr_str = ' '.join(f'{k}={v!r}' for k, v in attrs.items())
            attr_part = f" [{attr_str}]" if attr_str else ""
        else:
            attr_part = ""
        text_val = getattr(self, 'text', None)
        text_part = f": {text_val!r}" if text_val is not None else ""
        header = f"{prefix}{cls_name}{id_part}{attr_part}{text_part}"
        lines.append(header)
        if debug:
            lines.append(f"{prefix}  <debug: {hex(id(self))}>")
        # Handle children
        children = getattr(self, 'children', None)
        if children is not None:
            try:
                for child in children:
                    if hasattr(child, 'pretty') and callable(child.pretty):
                        lines.append(child.pretty(indent=indent+2, debug=debug))
                    else:
                        lines.append(f"{' ' * (indent+2)}{repr(child)}")
            except Exception as e:
                lines.append(f"{' ' * (indent+2)}<Error iterating children: {e}>")
        return '\n'.join(lines)
    except Exception as e:
        return f"<Error pretty printing {self.__class__.__name__}: {e}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper predicates for a simple tuple-based representation:
    #   ('&', left, right)  for conjunction
    #   ('|', left, right)  for disjunction
    #   ('~', expr)         for negation
    def is_neg(expr):
        return isinstance(expr, tuple) and expr[0] == '~'

    def is_conj(expr):
        return isinstance(expr, tuple) and expr[0] == '&'

    def is_disj(expr):
        return isinstance(expr, tuple) and expr[0] == '|'

    def get_left(expr):
        return expr[1] if isinstance(expr, tuple) else None

    def get_right(expr):
        return expr[2] if isinstance(expr, tuple) and len(expr) > 2 else None

    def contains(expr, sub):
        """Return True if sub is structurally equal to expr or any sub‑expression."""
        if expr == sub:
            return True
        if is_neg(expr):
            return contains(expr[1], sub)
        if is_conj(expr) or is_disj(expr):
            return contains(expr[1], sub) or contains(expr[2], sub)
        return False

    def replace(expr, old, new):
        """Replace all occurrences of old in expr with new."""
        if expr == old:
            return new
        if is_neg(expr):
            return ('~', replace(expr[1], old, new))
        if is_conj(expr) or is_disj(expr):
            return (expr[0], replace(expr[1], old, new

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    sys = __import__('sys')
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            try:
                result = namefunc(*args, **kwargs)
            except Exception:
                # propagate any exception from the original function
                raise
            # In Python 2, unicode type exists; encode to bytes if needed
            try:
                if isinstance(result, unicode):
                    return result.encode('utf-8')
            except NameError:
                # unicode not defined (Python 3 path), but we are in Python 2 branch
                pass
            return result
        return wrapper
    else:
        # In Python 3, the original function already returns a str (unicode)
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata as importlib_metadata
    except ImportError:
        try:
            import importlib_metadata
        except ImportError:
            return 'unknown'
    # Determine the package name from the module's package or name
    pkg_name = __package__ or __name__
    if '.' in pkg_name:
        pkg_name = pkg_name.split('.')[0]
    try:
        return importlib_metadata.version(pkg_name)
    except Exception:
        return 'unknown'

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if pieces is None:
        pieces = []
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    try:
        # Convert each piece to string safely
        str_pieces = [str(p) for p in pieces]

        style_lower = style.lower()
        if style_lower == "html":
            # Simple HTML rendering: separate pieces with <br>
            return "<br>".join(str_pieces)
        elif style_lower == "text":
            # Plain text rendering: separate pieces with newlines
            return "\n".join(str_pieces)
        elif style_lower == "json":
            # JSON rendering: encode the list of strings
            import json
            return json.dumps(str_pieces)
        else:
            raise ValueError(f"Unsupported style: {style!r}")
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError for clarity
        raise RuntimeError(f"Error rendering pieces: {exc}") from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate input
    if pieces is None:
        raise TypeError("pieces must be an iterable, got None")
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError(f"pieces must be an iterable, got {type(pieces).__name__}")

    # Check for existing '+'
    for item in iterator:
        # If item is a string, check if it contains '+'
        if isinstance(item, str):
            if '+' in item:
                return '.'
        # If item is not a string, check if it equals '+'
        else:
            if item == '+':
                return '.'

    # No '+' found
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        # Simple split; does not handle quoted arguments
        cmd_list = commands.split()
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        cmd_list += list(args)

    # Merge environment variables
    env_dict = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_dict.update(env)

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(cmd_list)}")
        if cwd:
            print(f"Working directory: {cwd}")

    # Execute the command
    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env_dict,
            capture_output=True,
            text=True,
            stderr=subprocess.DEVNULL if hide_stderr else None
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd_list[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {' '.join(cmd_list)}

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not callable(method):
        raise TypeError("method must be callable")

    # Register the handler in a global registry
    global _vcs_handlers
    try:
        _vcs_handlers
    except NameError:
        _vcs_handlers = {}

    if vcs in _vcs_handlers:
        raise ValueError(f"Handler for VCS '{vcs}' is already registered")

    _vcs_handlers[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the hierarchy.  We assume the instance is iterable
    # and yields all descendant objects (including itself if desired).
    try:
        iterator = iter(self)
    except TypeError:
        # If the object is not iterable, treat it as a single object
        iterator = [self]

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    if not obj.validate():
                        is_valid = False
                else:
                    # If no validate method, assume valid
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation error for object {obj!r}: {exc}")

        # Check the digest if requested
        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_valid = False
                else:
                    # If no check_digest method, assume valid
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check error for object {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    from pathlib import Path

    # Determine the root path from the instance
    try:
        root_path = Path(self.path)
    except AttributeError:
        raise AttributeError("The instance must have a 'path' attribute pointing to the desired storage root.")

    # Ensure the root path is not an existing file
    if root_path.exists() and root_path.is_file():
        raise FileExistsError(f"Path '{root_path}' exists and is a file, expected a directory for the OCFL root.")

    # Create the root directory if it does not exist
    if not root_path.exists():
        try:
            root_path.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise OSError(f"Failed to create OCFL root directory '{root_path}': {exc}") from exc

    # If the directory exists but is not empty, raise an error
    if root_path.exists() and any(root_path.iterdir()):
        raise FileExistsError(f"OCFL root directory '{root_path}' already exists and is not empty.")

    # Create the .ocfl_root file with a minimal version declaration
    ocfl_root_file = root_path / ".ocfl_root"
    try:
        ocfl_root_file.write_text("ocfl_version: 1.0\n")
    except OSError as exc:
        raise OSError(f"Failed to write .ocfl_root file at '{ocfl_root_file}': {exc}") from exc

    # Create the objects directory inside the root
    objects_dir = root_path / "objects"
    try:
        objects_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to create objects directory '{objects_dir}': {exc}") from exc

    # Optionally create a placeholder file to keep the directory in version control
    placeholder_file = objects_dir / ".gitkeep"
    try:
        placeholder_file.touch(exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to create placeholder file '{placeholder_file}': {exc}") from exc

    # Store the resolved root path on the instance for later use
    self.root = root_path
    return None

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("empty version string")
    parts = version.split('.')
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid version part '{p}' in '{version}'")
    last = parts[-1]
    width = len(last)
    new_last = str(int(last) + 1)
    if len(new_last) < width:
        new_last = new_last.zfill(width)
    parts[-1] = new_last
    return '.'.join(parts)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        # Normalize path
        path = os.fspath(path)
    except Exception as e:
        return f"invalid path: {e}"

    if not os.path.exists(path):
        return "path does not exist"

    if os.path.isfile(path):
        return "file"

    if os.path.isdir(path):
        # Look for a file matching "0=*"
        try:
            namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
        except Exception as e:
            return f"cannot list directory: {e}"
        if not namaste_files:
            return "not an OCFL directory (no Namaste file found)"
        # Check for presence of an "objects" subdirectory to distinguish root
        objects_dir = os.path.join(path, "objects")
        if os.path.isdir(objects_dir):
            return "root"
        else:
            return "object"

    return "unknown path type"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Validate inputs
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        raise ValueError("bug_ids cannot be None")

    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, str):
        # Split on commas or whitespace
        bug_ids = [bid.strip() for bid in bug_ids.replace(',', ' ').split() if bid.strip()]
    elif isinstance(bug_ids, (list, tuple)):
        bug_ids = [str(bid).strip() for bid in bug_ids if str(bid).strip()]
    else:
        raise TypeError("bug_ids must be a string, list, or tuple")

    if not bug_ids:
        raise ValueError("bug_ids must contain at least one id")

    # Merge with any existing 'ids' entry in params
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_list = [e.strip() for e in existing.replace(',', ' ').split() if e.strip()]
        else:
            existing_list = list(existing)
        combined = existing_list + bug_ids
        params['ids'] = ','.join(combined)
    else:
        params['ids'] = ','.join(bug_ids)

    return params

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    try:
        # Ensure the object looks like an ArgumentParser
        actions = getattr(parser, 'actions', None)
        if actions is None:
            raise TypeError("Expected an argparse.ArgumentParser instance")

        flags = []
        for action in actions:
            option_strings = getattr(action, 'option_strings', None)
            if option_strings:
                flags.extend(option_strings)

        return ' '.join(flags)
    except Exception as exc:
        raise ValueError(f"Unable to extract flags from parser: {exc}") from exc

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic input validation
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')
    if not hasattr(unparsed_arguments, '__iter__'):
        raise TypeError('unparsed_arguments must be an iterable of argument strings')

    parsed = {}
    remaining_sets = []

    for name, parser in subparsers.items():
        # Ensure parser has the expected method
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Parser for "{name}" does not have parse_known_args method')
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails (e.g., SystemExit), treat as no arguments parsed
            namespace = None
            remaining = list(unparsed_arguments)
        parsed[name] = namespace
        remaining_sets.append(set(remaining))

    # Determine arguments not claimed by any subparser
    if remaining_sets:
        # Intersection of all remaining sets gives arguments that were not parsed by any parser
        unclaimed_set = set.intersection(*remaining_sets)
        remaining_args = [arg for arg in unparsed_arguments if arg in unclaimed_set]
    else:
        remaining_args = list(unparsed_arguments)

    return parsed, remaining_args

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser(description='Main application parser')
        subparsers = parser.add_subparsers(dest='command', required=True)
        return parser, subparsers
    except Exception as e:
        raise RuntimeError('Failed to create parsers') from e

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not nodes:
        return []

    def is_mapping_node(node):
        """Return True if node is a MappingNode (has a list of key/value tuples)."""
        return hasattr(node, 'value') and isinstance(node.value, list)

    def merge_mapping_nodes(node1, node2):
        """Deep merge two MappingNode instances and return a new MappingNode."""
        # Copy the first node's value list
        merged_value = list(node1.value)
        # Build index of keys in the first mapping
        key_index = {k.value: i for i, (k, _) in enumerate(merged_value)}
        for k2, v2 in node2.value:
            key = k2.value
            if key in key_index:
                i = key_index[key]
                k1, v1 = merged_value[i]
                if is_mapping_node(v1) and is_mapping_node(v2):
                    merged_v = merge_mapping_nodes(v1, v2)
                    merged_value[i] = (k1, merged_v)
                else:
                    # last wins
                    merged_value[i] = (k1, v2)
            else:
                merged_value.append((k2, v2))
                key_index[key] = len(merged_value) - 1
        # Create a new node of the same type as node1
        return type(node1)(tag=node1.tag, value=merged_value)

    result = []
    key_index = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_val_node = result[idx]
            if is_mapping_node(existing_val_node) and is_mapping_node(val_node):
                merged = merge_mapping_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged)
            else:
                # last wins
                result[idx] = (existing_key_node, val_node)
        else:
            key_index[key] = len(result)
            result.append((key_node, val_node))
    return result

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    try:
        # Basic validation: parser should have the expected attribute
        if not hasattr(parser, "_actions"):
            raise TypeError("Provided object does not appear to be an argparse.ArgumentParser instance.")
        flags = []
        for action in parser._actions:
            # action.option_strings may be empty for positional arguments
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        # Remove duplicates and sort for deterministic output
        unique_flags = sorted(set(flags))
        return " ".join(unique_flags)
    except Exception as exc:
        raise ValueError(f"Failed to extract flags from parser: {exc}") from exc

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        # Try to import argcomplete for generating the script
        import argcomplete
    except ImportError as exc:
        return f"# Error: argcomplete is not installed ({exc})\n"

    try:
        # Attempt to obtain the borgmatic parser
        try:
            # Borgmatic may expose a get_parser function
            from borgmatic.main import get_parser
        except Exception:
            # Fallback: import the module and look for get_parser
            import borgmatic.main as bm_main
            if hasattr(bm_main, 'get_parser'):
                get_parser = bm_main.get_parser
            else:
                raise RuntimeError("Unable to locate borgmatic parser (no get_parser function).")

        parser = get_parser()
        if parser is None:
            raise RuntimeError("get_parser() returned None.")
    except Exception as exc:
        return f"# Error obtaining borgmatic parser: {exc}\n"

    try:
        # Generate the bash completion script using argcomplete
        script = argcomplete.completion.get_bash_completion_script(parser, 'borgmatic')
        return script
    except Exception as exc:
        return f"# Error generating completion script: {exc}\n"

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if not hasattr(unparsed_arguments, '__iter__'):
        raise TypeError('unparsed_arguments must be an iterable of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')

    parsed_results = {}
    claimed_args_set = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Subparser for "{name}" does not appear to be an ArgumentParser')
        try:
            namespace, remaining = parser.parse_known_args(list(unparsed_arguments))
        except Exception as exc:
            raise ValueError(f'Error parsing arguments for subparser "{name}": {exc}') from exc

        parsed_results[name] = namespace
        # Determine which arguments were claimed by this parser
        # Claimed args are those that were removed from the original list
        claimed = set(unparsed_arguments) - set(remaining)
        claimed_args_set.update(claimed)

    # Remaining arguments are those not claimed by any subparser
    remaining_all = [arg for arg in unparsed_arguments if arg not in claimed_args_set]

    return parsed_results, remaining_all

def make_parsers():
    """Build a top-level parser and its subparsers and return them as a tuple."""
    try:
        import argparse
    except ImportError as exc:
        raise RuntimeError("argparse module is required to build parsers") from exc

    parser = argparse.ArgumentParser(description="Main application")
    subparsers = parser.add_subparsers(dest="command", required=True)
    return parser, subparsers

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"All items must be dictionaries, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as exc:
                    raise TypeError(f"Cannot add values for key {key!r}: {exc}") from exc
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Basic type checks
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    # Pattern for placeholders like {key}
    import re
    placeholder_pattern = re.compile(r'\{([^{}]+)\}')

    def _replace_match(match):
        key = match.group(1)
        if key in url_args:
            # Convert the value to string; quote if it contains unsafe characters
            value = str(url_args[key])
            return value
        # If key not found, leave placeholder unchanged
        return match.group(0)

    try:
        return placeholder_pattern.sub(_replace_match, url)
    except Exception as exc:
        raise ValueError(f"Error replacing URL arguments: {exc}") from exc

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None is considered a None value
    if val is None:
        return True

    # Only strings are considered for textual None representations
    if not isinstance(val, str):
        return False

    # Normalize the string: strip whitespace and convert to lower case
    stripped = val.strip().lower()

    # Common textual representations of None
    none_representations = {"none", "null", "nan", ""}

    return stripped in none_representations

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not hasattr(parser, '_actions'):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            if hasattr(action, 'option_strings') and action.option_strings:
                flags.extend(action.option_strings)
        return ' '.join(flags)
    except Exception as e:
        raise RuntimeError(f"Error extracting flags from parser: {e}") from e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    base = len(alphabet)
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    try:
        return value.replace('.', arg)
    except Exception as e:
        raise RuntimeError(f"Error replacing dots: {e}") from e

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"subclasses() expects a class type, got {type(cls).__name__}")
    result = set()

    def _collect(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _collect(sub)

    _collect(cls)
    return list(result)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not all(isinstance(ch, str) and len(ch) == 1 for ch in alphabet):
        raise TypeError("alphabet must contain single-character strings")

    # Alphabet validation
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate characters")

    base = len(alphabet)
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Empty string maps to 0
    if string == "":
        return 0

    result = 0
    for idx, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' at position {idx} not in alphabet")
        result = result * base + char_to_value[ch]

    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # Fallback for systems where os.uname() is not available (e.g., Windows)
        import sys
        return sys.platform.startswith('darwin')

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    try:
        # Remove leading and trailing single or double quotes
        return re.sub(r"^['\"]+|['\"]+$", "", name)
    except re.error as exc:
        raise ValueError(f"Regex error while unquoting name: {exc}") from exc

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:  # POSIX
        # Matches double-quoted, single-quoted, or unquoted tokens
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                # double-quoted: handle backslash escapes
                arg = m.group(1).replace(r'\"', '"').replace(r'\\', '\\')
            elif m.group(2) is not None:
                # single-quoted: no escapes
                arg = m.group(2)
            else:
                arg = m.group(3)
            args.append(arg)
        return args
    elif platform == 0:  # Windows
        # Matches double-quoted (with escapes), single-quoted, or unquoted tokens
        pattern = re.compile(r'''(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|(\S+))''')
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                raw = m.group(1)
                # Unescape Windows quoting rules
                arg = ''
                i = 0
                while i < len(raw):
                    if raw[i] == '\\':
                        bs = 0
                        while i < len(raw) and raw[i] == '\\':
                            bs += 1
                            i += 1
                        if i < len(raw) and raw[i] == '"':
                            arg += '\\' * (bs // 2)
                            if bs % 2 == 1:
                                arg += '"'
                                i += 1
                        else:
                            arg += '\\' * bs
                    else:
                        arg += raw[i]

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT
        )
        files = output.decode('utf-8').splitlines()
        files.sort()
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''

def match(filename):
    """Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename)
        ext = ext.lower()
        supported_extensions = {'.txt', '.md', '.json', '.xml', '.csv'}
        return ext in supported_extensions
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str):
        raise TypeError('config_filename must be a string')
    if not isinstance(rendered_config, str):
        raise TypeError('rendered_config must be a string')
    if not isinstance(mode, int):
        raise TypeError('mode must be an integer')
    if not isinstance(overwrite, bool):
        raise TypeError('overwrite must be a boolean')

    # Ensure directory exists
    dir_name = os.path.dirname(config_filename)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            raise OSError(f'Failed to create directories for {config_filename!r}: {exc}') from exc

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f'File {config_filename!r} already exists and overwrite is False')

    # Write the file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set file permissions
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise OSError(f'Failed to write configuration to {config_filename!r}: {exc}') from exc
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise TypeError("matcher must be a string, got None")
    if not isinstance(matcher, str):
        raise TypeError(f"matcher must be a string, got {type(matcher).__name__}")
    matcher = matcher.strip()
    if not matcher:
        raise ValueError("matcher cannot be an empty string")

    # Split into name and optional default
    if ':' in matcher:
        name, default = matcher.split(':', 1)
        name = name.strip()
        default = default.strip()
        if not name:
            raise ValueError("environment variable name cannot be empty")
    else:
        name = matcher
        default = None

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' is not set and no default value provided")
    return value

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import os
    # Validate inputs
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a bool")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a bool")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Merge environment variables
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    results = []
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("Each command must be a string")
        full_cmd = [cmd] + list(args)
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env_dict,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=True
            )
            results.append(result)
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command '{' '.join(full_cmd)}' failed with return code {e.returncode}")
                if not hide_stderr:
                    print(e.stderr)
            raise RuntimeError(f"Command '{' '.join(full_cmd)}' failed") from e
    return results

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper:
            s = yaml.dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True,
            )
        else:
            s = yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True,
            )
    except yaml.YAMLError as exc:
        raise ValueError(f"YAML dump error: {exc}")

    # Ensure the result is a unicode string on Python 2 and a str on Python 3
    if isinstance(s, bytes):
        try:
            s = s.decode("utf-8")
        except Exception:
            s = s.decode("latin1")
    return s

