def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x)
    except Exception as e:
        raise TypeError("Input x must be a number or array-like") from e
    mu = 0.2
    sigma = 0.1
    return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re
    # Optional YAML support
    try:
        import yaml
    except Exception:
        yaml = None

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')

    def _resolve_env(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    # Validate inputs
    if not hasattr(config_filenames, '__iter__') or isinstance(config_filenames, (str, bytes)):
        raise TypeError('config_filenames must be an iterable of filenames')
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError('overrides must be a dict or None')
    if not isinstance(resolve_env, bool):
        raise TypeError('resolve_env must be a boolean')

    configs = {}
    error_records = []

    for fname in config_filenames:
        if not isinstance(fname, str):
            msg = f'Configuration filename must be a string, got {type(fname).__name__}'
            record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
            error_records.append(record)
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            msg = f'Failed to read file {fname}: {exc}'
            record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
            error_records.append(record)
            continue

        parsed = None
        # Try JSON first
        try:
            parsed = json.loads(content)
        except Exception:
            # Try YAML if available
            if yaml is not None:
                try:
                    parsed = yaml.safe_load(content)
                except Exception as exc:
                    msg = f'Failed to parse YAML in {fname}: {exc}'
                    record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
                    error_records.append(record)
                    continue
            else:
                msg = f'Failed to parse JSON in {fname} and PyYAML not available'
                record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
                error_records.append(record)
                continue

        if parsed is None:
            msg = f'Parsed configuration is None for {fname}'
            record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
            error_records.append(record)
            continue

        # Apply overrides if provided
        if overrides:
            if isinstance(parsed, dict):
                # Merge overrides into parsed config
                merged = parsed.copy()
                merged.update(overrides)
                parsed = merged
            else:
                # Cannot merge non-dict config with overrides
                msg = f'Cannot apply overrides to non-dict configuration in {fname}'
                record = logging.LogRecord(__name__, logging.WARNING, fname, 0, msg, None, None)
                error_records.append(record)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = _resolve_env(parsed)
            except Exception as exc:
                msg = f'Error resolving environment variables in {fname}: {exc}'
                record = logging.LogRecord(__name__, logging.ERROR, fname, 0, msg, None, None)
                error_records.append(record)

        configs[fname] = parsed

    return configs, error_records

def force_string(obj):
    """This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8."""
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Failed to encode string to UTF-8: {e}") from e
    elif isinstance(obj, bytes):
        return obj
    else:
        raise TypeError(f"force_string expects a str or bytes, got {type(obj).__name__}")

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values cannot be None")

    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    instance = cls()

    for v in iterator:
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")

        v_clean = v.strip()
        if not v_clean:
            continue

        # Try to add the bookmark using a common interface
        if hasattr(instance, "add") and callable(instance.add):
            try:
                instance.add(v_clean)
            except Exception as exc:
                raise ValueError(f"Failed to add bookmark '{v_clean}': {exc}") from exc
        elif hasattr(instance, "bookmarks") and isinstance(instance.bookmarks, list):
            instance.bookmarks.append(v_clean)
        else:
            # Fallback: create a 'bookmarks' list attribute if it doesn't exist
            if not hasattr(instance, "bookmarks"):
                instance.bookmarks = []
            instance.bookmarks.append(v_clean)

    return instance

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Import here to avoid global imports
    from collections.abc import Iterable
    import itertools

    # Helper to determine if an object is a sequence type that we can return as-is
    def _is_sequence_type(obj):
        return isinstance(obj, (list, tuple, set, dict, str, bytes, bytearray, memoryview))

    # If seq is already a sequence type, return it (possibly sliced)
    if _is_sequence_type(seq):
        if bufsize is not None:
            # Try slicing if supported
            try:
                sliced = seq[:bufsize]
                return sliced, type(sliced)
            except Exception:
                # Fallback: convert to list and slice
                sliced = list(seq)[:bufsize]
                return sliced, type(sliced)
        return seq, type(seq)

    # For other iterables, materialise into a list (or limited slice)
    if not isinstance(seq, Iterable):
        raise TypeError(f"Object {seq!r} is not iterable")

    try:
        if bufsize is not None:
            seq_list = list(itertools.islice(seq, bufsize))
        else:
            seq_list = list(seq)
    except Exception as exc:
        raise TypeError(f"Failed to iterate over {seq!r}") from exc

    return seq_list, type(seq_list)

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate!r} does not provide interface {iface.__name__}")
    for name in iface.getRequiredMethods():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method {name}")
        else:
            cand_method = getattr(candidate, name)
            iface_method = getattr(iface, name)
            try:
                cand_sig = cand_method.__code__.co_varnames[:cand_method.__code__.co_argcount]
                iface_sig = iface_method.__code__.co_varnames[:iface_method.__code__.co_argcount]
                if cand_sig != iface_sig:
                    errors.append(f"Signature mismatch for method {name}: expected {iface_sig}, got {cand_sig}")
            except AttributeError:
                pass
    for name in iface.getRequiredAttributes():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute {name}")
    if errors:
        if len(errors) == 1:
            raise

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Interface provision check
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not provide interface {iface.__name__}")
        except Exception as exc:
            errors.append(f"Error checking interface provision: {exc!r}")

    # 2. Required methods
    try:
        required_methods = iface.getRequiredMethods()
    except Exception:
        required_methods = []

    # 3. Required attributes
    try:
        required_attrs = iface.getRequiredAttributes()
    except Exception:
        required_attrs = []

    # Import inspect lazily
    inspect = __import__('inspect')

    # Helper to compare signatures
    def signatures_match(iface_sig, cand_sig):
        # Remove 'self' from candidate signature if present
        params = list(cand_sig.parameters.values())
        if params and params[0].name == 'self':
            params = params[1:]
        cand_sig = inspect.Signature(parameters=params)

        # Compare number of parameters
        if len(iface_sig.parameters) != len(cand_sig.parameters):
            return False
        # Compare parameter names and kinds
        for iface_p, cand_p in zip(iface_sig.parameters.values(), cand_sig.parameters.values()):
            if iface_p.name != cand_p.name or iface_p.kind != cand_p.kind:
                return False
        return True

    # Check methods
    for name in required_methods:
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        method = getattr(candidate, name)
        if not callable(method):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        # Get interface method signature
        try:
            iface_method = iface.getMethod(name)
            iface_sig = iface_method.__signature__
        except Exception:
            # If interface method signature not available, skip signature check
            iface_sig = None
        if iface_sig is not None:
            try:
                cand_sig = inspect.signature(method)
                if not signatures_match(iface_sig, cand_sig):
                    errors.append(f"Signature mismatch for method '{name}': expected {iface_sig}, got {cand_sig}")
            except Exception as exc:
                errors.append(f"Error inspecting signature of method '{name}': {exc!r}")

    # Check attributes
    for name in required_attrs:
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            msg = "Multiple interface validation errors:\n" + "\n".join(errors)
            raise zope.interface.Invalid(msg)

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Basic validation of inputs
    if iface is None or candidate is None:
        raise ValueError("Both 'iface' and 'candidate' must be provided and not None.")
    if not isinstance(iface, type):
        raise TypeError(f"'iface' must be a class/type, got {type(iface).__name__}.")
    if not isinstance(candidate, type):
        raise TypeError(f"'candidate' must be a class/type, got {type(candidate).__name__}.")

    # If candidate is already a subclass of iface, it's valid
    if issubclass(candidate, iface):
        return True

    # Determine the set of required attributes/methods
    required = set()
    try:
        required.update(getattr(iface, "__abstractmethods__", set()))
    except Exception:
        required = set()

    # If no abstractmethods defined, fall back to checking public callables
    if not required:
        for name in dir(iface):
            if name.startswith("_"):
                continue
            attr = getattr(iface, name, None)
            if callable(attr):
                required.add(name)

    missing = [name for name in required if not hasattr(candidate, name)]

    if missing:
        if tentative:
            # In tentative mode, simply return False if any requirement is missing
            return False
        else:
            missing_str = ", ".join(missing)
            raise AttributeError(
                f"Candidate class '{candidate.__name__}' does not implement required "
                f"attributes/methods for interface '{iface.__name__}': {missing_str}"
            )

    return True

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Determine the underlying container that holds the items.
    container = getattr(self, "_data", None)
    if container is None:
        container = getattr(self, "data", None)
    if container is None:
        raise TypeError("popitem requires an underlying OrderedDict-like container")

    try:
        # `popitem(last=False)` removes the first (least recently used) item.
        return container.popitem(last=False)
    except KeyError:
        # The container is empty.
        raise KeyError("popitem from an empty container")
    except Exception as exc:
        # Any other unexpected error is wrapped for clarity.
        raise RuntimeError(f"Unexpected error during popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return super().popitem()
    except AttributeError:
        # Fallback for objects that store items in an internal dict named 'data'
        if hasattr(self, 'data') and isinstance(self.data, dict):
            try:
                return self.data.popitem()
            except KeyError as e:
                raise KeyError("popitem(): dictionary is empty") from e
        else:
            raise TypeError("popitem() not supported for this object")
    except KeyError as e:
        raise KeyError("popitem(): dictionary is empty") from e

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    value = self[key]
    del self[key]
    return key, value

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        return _converting._Converter()
    except Exception as e:
        raise RuntimeError("Failed to create parameter style converter") from e

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if not isinstance(request, RequestType):
        raise TypeError(f"Expected RequestType instance, got {type(request).__name__}")

    try:
        # Check for a public message first
        if getattr(request, "public_message", None):
            return True

        # If no public message, check for a private message
        if getattr(request, "private_message", None):
            return True

        # Finally, check for a legacy payload
        if getattr(request, "legacy_payload", None):
            return True
    except Exception:
        # Any unexpected error during attribute access should result in a negative identification
        return False

    # If none of the expected attributes are present, it's not a Diaspora request
    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    try:
        # Handle None or empty request
        if request is None:
            return False

        # If request is a dict-like object
        if isinstance(request, dict):
            # Check common keys that might indicate a Matrix request
            for key in ("type", "request_type", "matrix", "matrix_data"):
                if key in request:
                    val = request[key]
                    if isinstance(val, str) and val.lower() == "matrix":
                        return True
                    if key in ("matrix", "matrix_data"):
                        return True
            return False

        # If request has attributes that might indicate a Matrix request
        for attr in ("type", "request_type", "matrix", "matrix_data"):
            if hasattr(request, attr):
                val = getattr(request, attr)
                if isinstance(val, str) and val.lower() == "matrix":
                    return True
                if attr in ("matrix", "matrix_data"):
                    return True

        # Fallback: check string representation for the word "matrix"
        if "matrix" in str(request).lower():
            return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        raise ValueError("dt must not be None")
    # Ensure dt has isoformat and drop microseconds if present
    try:
        if hasattr(dt, "microsecond") and dt.microsecond:
            dt = dt.replace(microsecond=0)
        s = dt.isoformat()
    except Exception as e:
        raise TypeError("dt must be a datetime or date instance") from e
    # Convert UTC offset to 'Z' if applicable
    if hasattr(dt, "tzinfo") and dt.tzinfo is not None:
        offset = dt.tzinfo.utcoffset(dt)
        if offset is not None and offset.total_seconds() == 0:
            if s.endswith("+00:00"):
                s = s[:-6] + "Z"
    return s

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url:
        return None
    try:
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re
    if not isinstance(tag, str):
        raise TypeError(f"tag must be a string, got {type(tag).__name__}")
    # Tags must start with a letter, can contain letters, digits, hyphens, or underscores
    pattern = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an Element-like object with iterable children") from exc

    result = {}
    for child in children:
        tag = getattr(child, "tag", None)
        if tag is None:
            continue
        if tag in result:
            # If we already have a single element, convert to list
            if isinstance(result[tag], list):
                result[tag].append(child)
            else:
                result[tag] = [result[tag], child]
        else:
            result[tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if not isinstance(sender_handle, str):
        raise TypeError(f"sender_handle must be a string, got {type(sender_handle).__name__}")
    if not isinstance(entity_handle, str):
        raise TypeError(f"entity_handle must be a string, got {type(entity_handle).__name__}")
    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'")
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Default path to the NodeInfo document if none supplied
    if document_path is None:
        document_path = "/.well-known/nodeinfo/2.0"

    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Construct the full href, avoiding duplicate slashes
    href = url.rstrip("/") + document_path

    # Return the well‑known NodeInfo document structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic input validation
    if public_key is None or doc is None or signature is None:
        raise ValueError("public_key, doc, and signature must all be provided")

    # Import required modules locally to avoid top‑level imports
    try:
        import base64
        import xml.etree.ElementTree as ET
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception as exc:
        raise RuntimeError("Required cryptographic libraries are missing") from exc

    # Load the public key if it is given as a PEM string
    try:
        if isinstance(public_key, str):
            public_key = serialization.load_pem_public_key(public_key.encode("utf-8"))
        elif hasattr(public_key, "verify"):
            # Assume it is already a key object
            pass
        else:
            raise TypeError("public_key must be a PEM string or a cryptography key object")
    except Exception as exc:
        raise ValueError("Failed to load public key") from exc

    # Parse the signature XML and extract the base64 encoded signature value
    try:
        sig_root = ET.fromstring(signature)
        # Namespace-aware search for SignatureValue
        ns = {"ds": "http://www.w3.org/2000/09/xmldsig#"}
        sig_value_elem = sig_root.find(".//ds:SignatureValue", ns)
        if sig_value_elem is None or not sig_value_elem.text:
            raise ValueError("SignatureValue element not found or empty")
        sig_bytes = base64.b64decode(sig_value_elem.text)
    except Exception as exc:
        raise ValueError("Invalid signature XML format") from exc

    # Compute the digest of the document to be verified
    try:
        if isinstance(doc, ET.Element):
            doc_bytes = ET.tostring(doc, encoding="utf-8")
        else:
            doc_bytes = doc.encode("utf-8")
        digest = hashes.Hash(hashes.SHA256())
        digest.update(doc_bytes)
        digest_bytes = digest.finalize()
    except Exception as exc:
        raise RuntimeError("Failed to compute digest of the document") from exc

    # Verify the signature
    try:
        public_key.verify(
            sig_bytes,
            digest_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        # Any verification error results in a False return
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not isinstance(document, str):
        raise TypeError("document must be a string")
    if not document.strip():
        raise ValueError("document is empty")

    # Try JSON first
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        # Basic validation
        subject = data.get("subject")
        if not subject:
            raise ValueError("JSON webfinger missing 'subject'")
        aliases = data.get("aliases", [])
        if not isinstance(aliases, list):
            raise ValueError("'aliases' must be a list")
        links = data.get("links", [])
        if not isinstance(links, list):
            raise ValueError("'links' must be a list")
        # Ensure each link is a dict with required keys
        for link in links:
            if not isinstance(link, dict):
                raise ValueError("Each link must be a dict")
            if "rel" not in link or "href" not in link:
                raise ValueError("Each link must contain 'rel' and 'href'")
        return {"subject": subject, "aliases": aliases, "links": links}
    except json.JSONDecodeError:
        pass  # fall back to XRD parsing

    # XRD parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse webfinger: {e}")

    # Namespace handling: XRD uses http://docs.oasis-open.org/ns/xri/xrd-1.0
    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    # Helper to find text
    def _text(elem, tag):
        found = elem.find(f"{{{ns['xrd']}}}{tag}")
        return found.text.strip() if found is not None and found.text else None

    subject = _text(root, "Subject")
    if not subject:
        raise ValueError("XRD webfinger missing <Subject>")

    aliases = [a.text.strip() for a in root.findall(f"{{{ns['xrd']}}}Alias") if a.text]
    links = []
    for link_elem in root.findall(f"{{{ns['xrd']}}}Link"):
        rel = link_elem.get("rel")
        href = link_elem.get("href")
        type_ = link_elem.get("type")
        if not rel or not href:
            continue  # skip incomplete links
        link_dict = {"rel": rel, "href": href}
        if type_:
            link_dict["type"] = type_
        links.append(link_dict)

    return {"subject": subject, "aliases": aliases, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    if not isinstance(handle, str) or not handle:
        return None
    try:
        import urllib.request, urllib.error
        url = f"https://{handle}/.well-known/webfinger?resource=acct:{handle}"
        with urllib.request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.error
    import json

    # Validate handle format (must contain '@')
    if '@' not in handle:
        raise ValueError(f"Invalid Diaspora handle '{handle}'. Expected format 'user@domain'.")

    user, domain = handle.split('@', 1)
    # Construct the webfinger URL
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP error {resp.status} when retrieving {url}")
            raw = resp.read().decode('utf-8')
            try:
                return json.loads(raw)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON from {url}: {e}") from e
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error {e.code} when retrieving {url}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error when retrieving {url}: {e.reason}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error when retrieving {url}: {e}") from e

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    if not host:
        raise ValueError("host must be provided")

    # Build the host-meta URL
    if host.startswith(("http://", "https://")):
        url = host.rstrip("/") + "/.well-known/host-meta"
    else:
        url = f"https://{host}/.well-known/host-meta"

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"Failed to retrieve host-meta: HTTP {resp.status}")
            data = resp.read()
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error retrieving host-meta: {e}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error retrieving host-meta: {e}") from e
    except Exception as e:
        raise ValueError(f"Error retrieving host-meta: {e}") from e

    # Parse the XML
    try:
        root = ET.fromstring(data)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML: {e}") from e

    # Attempt to return an XRD instance if the class is available
    try:
        return XRD(root)
    except NameError:
        # Fallback: return the parsed ElementTree element
        return root

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic validation of inputs
    if not isinstance(url, str) or not url.startswith(("http://", "https://")):
        raise ValueError("url must be a string starting with 'http://' or 'https://'")
    if not isinstance(data, (dict, bytes)) and not hasattr(data, "read"):
        raise ValueError("data must be a dict, bytes, or a file-like object")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("timeout must be a positive number")
    if not isinstance(method, str):
        raise ValueError("method must be a string")

    method = method.lower()
    try:
        import requests
        # Use the appropriate request method
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except requests.exceptions.RequestException as exc:
        # Return None for status code and the exception instance
        return (None, exc)
    except Exception as exc:
        # Catch any other unexpected exception
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Validate settings_dirs
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or a list/tuple of strings")

    # Validate spec_option
    if spec_option is None:
        patterns = None
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    elif isinstance(spec_option, (list, tuple)):
        patterns = list(spec_option)
    else:
        raise TypeError("spec_option must be None, a string, or a list/tuple of strings")

    os_mod = __import__('os')
    fnmatch_mod = __import__('fnmatch')
    file_list = []

    for d in dirs:
        try:
            if not os_mod.path.isdir(d):
                continue
            for entry in os_mod.listdir(d):
                full_path = os_mod.path.join(d, entry)
                if not os_mod.path.isfile(full_path):
                    continue
                if patterns is None:
                    file_list.append(full_path)
                else:
                    for pat in patterns:
                        if fnmatch_mod.fnmatch(entry, pat):
                            file_list.append(full_path)
                            break
        except OSError:
            continue

    return sorted(file_list)

def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    # Lazy initialization of a singleton config manager
    if not hasattr(cls, "_ansible_config_manager"):
        try:
            # Assume AnsibleConfigManager is defined elsewhere in the package
            cls._ansible_config_manager = AnsibleConfigManager()
        except Exception as exc:
            # Wrap any exception to provide a clear error message
            raise RuntimeError("Unable to instantiate AnsibleConfigManager") from exc
    return cls._ansible_config_manager

