def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException('spec_content is None')
    # Parse YAML if a string is provided
    if isinstance(spec_content, str):
        try:
            spec_dict = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f'Error parsing YAML: {e}')
    elif isinstance(spec_content, dict):
        spec_dict = spec_content
    else:
        raise IRValidatorException('spec_content must be a string or dict')
    if not isinstance(spec_dict, dict):
        raise IRValidatorException('Parsed spec is not a dictionary')
    # Define required fields for the spec
    required_fields = ['name', 'type', 'data']
    missing = [field for field in required_fields if field not in spec_dict]
    if missing:
        raise IRValidatorException(f'Missing required fields: {", ".join(missing)}')
    return spec_dict

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file must be provided")

        try:
            with open(yaml_file, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        except Exception as exc:
            raise IRValidatorException(f"Failed to load YAML file '{yaml_file}': {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file '{yaml_file}' does not contain a mapping at the top level")

        # Determine required fields: use class attribute if defined, otherwise empty list
        required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
        if not isinstance(required_fields, (list, tuple)):
            raise IRValidatorException("REQUIRED_FIELDS must be a list or tuple of field names")

        missing = [field for field in required_fields if field not in data]
        if missing:
            missing_str = ", ".join(missing)
            raise IRValidatorException(f"Missing mandatory field(s) in '{yaml_file}': {missing_str}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    try:
        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dict")

        # Work on a copy so we don't modify the original
        resolved = dict(parser_dict)

        # Keep resolving until no include directives remain
        while True:
            includes = [
                key
                for key, val in resolved.items()
                if isinstance(val, dict) and "include" in val
            ]
            if not includes:
                break

            for key in includes:
                inc_key = resolved[key]["include"]
                if inc_key not in resolved:
                    raise KeyError(
                        f"Included group '{inc_key}' not found in parser_dict"
                    )
                inc_val = resolved[inc_key]
                if not isinstance(inc_val, dict):
                    raise TypeError(
                        f"Included group '{inc_key}' must be a dict"
                    )

                # Merge the included dict into the resolved dict
                for sub_key, sub_val in inc_val.items():
                    if sub_key not in resolved:
                        resolved[sub_key] = sub_val

                # Remove the include directive after merging
                del resolved[key]

        return resolved

    except Exception as exc:
        raise RuntimeError(f"Failed to resolve include groups: {exc}") from exc

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Validate that the instance has the expected attributes
    if not hasattr(self, 'spec') or not isinstance(self.spec, dict):
        raise AttributeError("Missing or invalid 'spec' attribute; expected a dict.")
    if not hasattr(self, 'args') or not isinstance(self.args, dict):
        raise AttributeError("Missing or invalid 'args' attribute; expected a dict.")

    resolved = {}
    for key, value in self.args.items():
        if value is None:
            # 1. Try to get a default from the spec dictionary
            try:
                default = self.spec.get(key)
                if default is not None:
                    resolved[key] = default
                    continue
            except Exception:
                # Any unexpected error while accessing spec is ignored
                pass

            # 2. Try to get a default from an environment variable
            try:
                import os
                env_key = f"{self.__class__.__name__.upper()}_{key.upper()}"
                env_val = os.getenv(env_key)
                if env_val is not None:
                    resolved[key] = env_val
                    continue
            except Exception:
                # os may not be available or getenv may fail; ignore
                pass

            # 3. If no default found, keep None
            resolved[key] = None
        else:
            resolved[key] = value

    return resolved

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checking
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the list of deprecated arguments.  If the attribute does not exist,
    # assume there are none.
    deprecated = getattr(self, "deprecated_args", set())
    if not isinstance(deprecated, (set, list, tuple)):
        # Normalise to a set for efficient lookup
        deprecated = set(deprecated)

    # Helper to format a warning message
    def _warn(arg_name, source):
        print(f"WARNING: Argument '{arg_name}' is deprecated and will be ignored. (source: {source})")

    # Check CLI arguments
    try:
        for arg in cli_args:
            if arg in deprecated:
                _warn(arg, "CLI")
    except Exception as exc:
        # Log the exception but do not stop execution
        print(f"ERROR while validating CLI deprecated arguments: {exc}")

    # Check answer file arguments
    try:
        for arg in answer_file_args:
            if arg in deprecated:
                _warn(arg, "Answer file")
    except Exception as exc:
        print(f"ERROR while validating answer file deprecated arguments: {exc}")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not command_name:
        raise ValueError("command_name must be provided")
    try:
        # Assume the object has a 'parser' attribute that holds command options
        parser = getattr(self, "parser", None)
        if parser is None:
            raise AttributeError("No parser attribute found on the object")
        # The parser may expose options as a dict or via a method
        if isinstance(parser, dict):
            spec = parser.get(command_name)
        else:
            # Try a common method name
            spec = getattr(parser, "get_options", lambda name: None)(command_name)
        if spec is None:
            raise KeyError(f"No options found for command '{command_name}'")
        # Ensure the result is a list
        if not isinstance(spec, list):
            spec = list(spec)
        return spec
    except Exception as exc:
        raise ValueError(f"Error retrieving options for command '{command_name}': {exc}") from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    silent = []
    for name, value in args.items():
        # Consider an argument silent if it is None or an empty container/string
        if value is None:
            silent.append(name)
        elif isinstance(value, (str, list, tuple, set, dict)) and not value:
            silent.append(name)
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the list of required argument names from the instance or class
    required = getattr(self, "REQUIRED_ARGS", None)
    if required is None:
        required = getattr(self.__class__, "REQUIRED_ARGS", None)
    if required is None:
        # If no REQUIRED_ARGS defined, nothing to validate
        return True

    # Ensure required is iterable of strings
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("REQUIRED_ARGS must be a list, tuple, or set of argument names")

    # Find missing arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Validate inputs
        if not isinstance(options_spec, (list, tuple)):
            raise TypeError("options_spec must be a list or tuple of option specs")
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of received arguments")

        required_args = []

        for opt in options_spec:
            # Each option spec should be a mapping
            if not isinstance(opt, dict):
                continue
            name = opt.get("name")
            if not name:
                continue

            required_when = opt.get("required_when")
            if required_when is None:
                continue

            try:
                # If required_when is a callable, call it with args
                if callable(required_when):
                    matched = required_when(args)
                else:
                    # Treat non-callable as a truthy value
                    matched = bool(required_when)
            except Exception as exc:
                # Log the exception and skip this option
                # (Assuming a logger is available; otherwise ignore)
                # If no logger, re-raise as ValueError
                raise ValueError(
                    f"Error evaluating required_when for option '{name}': {exc}"
                ) from exc

            if matched:
                required_args.append(name)

        return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the mapping of argument names to maximum allowed lengths.
    # Subclasses may define a `lengths` attribute; if not present, skip validation.
    max_lengths = getattr(self, "lengths", {})

    for name, value in args.items():
        # Skip validation if no maximum length is defined for this argument.
        if name not in max_lengths:
            continue

        max_len = max_lengths[name]
        if value is None:
            # None is considered acceptable regardless of length.
            continue

        try:
            length = len(value)
        except TypeError:
            # If the value has no length (e.g., an int), skip validation.
            continue

        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Allow None or empty arguments
    if args is None:
        return True

    # Convert list/tuple of pairs to dict if necessary
    if isinstance(args, (list, tuple)):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("args must be a dict or a list/tuple of key-value pairs") from exc

    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    # Determine which arguments have defined choices
    # Prefer a 'choices' mapping on the instance; fall back to a 'choice_args' list
    choices_map = getattr(self, "choices", {})
    choice_args = getattr(self, "choice_args", [])

    for key, value in args.items():
        # Skip keys that are not defined as choice arguments
        if key not in choices_map and key not in choice_args:
            continue

        # Retrieve the allowed set of values
        allowed = choices_map.get(key)
        if allowed is None:
            # If only a list of choice argument names is provided, we cannot determine allowed values
            # In that case, skip validation for this key
            continue

        if value not in allowed:
            raise ValueError(
                f"Invalid value for argument '{key}': {value!r}. "
                f"Allowed choices: {allowed}"
            )

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure min and max attributes exist
    try:
        min_val = getattr(self, 'min', None)
        max_val = getattr(self, 'max', None)
    except Exception as exc:
        raise ValueError(f"Unable to access min/max attributes: {exc}") from exc

    # If no bounds are defined, nothing to validate
    if min_val is None or max_val is None:
        return

    # Handle None or empty args gracefully
    if args is None:
        return

    # Determine how to iterate over the arguments
    if isinstance(args, dict):
        iterable = args.items()
    else:
        # Assume iterable of values; use indices for reporting
        iterable = enumerate(args)

    for key, value in iterable:
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument {key!r} with value {value!r} is out of bounds "
                    f"[{min_val!r}, {max_val!r}]."
                )
        except TypeError as exc:
            # Value not comparable to min/max
            raise TypeError(
                f"Argument {key!r} with value {value!r} is not comparable to "
                f"min/max values."
            ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Basic type checks
            if not isinstance(subcommand, str):
                raise TypeError("subcommand must be a string")
            if not isinstance(type_name, str):
                raise TypeError("type_name must be a string")
            if not isinstance(option_name, str):
                raise TypeError("option_name must be a string")
            if not isinstance(spec_option, dict):
                raise TypeError("spec_option must be a dict")

            # Ensure required spec keys are present
            required_keys = ["type", "help"]
            missing = [k for k in required_keys if k not in spec_option]
            if missing:
                raise ValueError(f"spec_option missing required keys: {', '.join(missing)}")

            # Build a simple representation of the complex type
            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "spec": spec_option,
                "default": spec_option.get("default"),
                "required": spec_option.get("required", False),
            }

            # If the spec includes a callable type, validate it
            if callable(spec_option["type"]):
                # Test the callable with a dummy value if possible
                try:
                    spec_option["type"]("dummy")
                except Exception:
                    # It's okay if the type cannot be called with a dummy value
                    pass

            return complex_type

        except Exception as exc:
            raise RuntimeError(
                f"Failed to create complex argument type for option '{option_name}'"
            ) from exc

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Accept either a dict or an iterable of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = iter(args)
        except TypeError:
            raise TypeError("args must be a dict or an iterable of key/value pairs")

    for item in items:
        # Handle dict items
        if isinstance(item, tuple) and len(item) == 2:
            key, value = item
        elif isinstance(item, dict):
            # If a dict is passed as an element, merge it
            for k, v in item.items():
                key, value = k, v
                # Continue processing below
                if isinstance(key, str) and key.startswith('_'):
                    control_args[key] = value
                else:
                    nested_args[key] = value
            continue
        else:
            # Skip invalid items
            continue

        if not isinstance(key, str):
            # Skip non-string keys
            continue

        if key.startswith('_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Optional type mapping that subclasses may provide
    type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})

    def _cast_value(val, target_type):
        """Attempt to cast val to target_type, raising ValueError on failure."""
        if target_type is int:
            return int(val)
        if target_type is float:
            return float(val)
        if target_type is bool:
            if isinstance(val, str):
                return val.lower() in ("true", "1", "yes")
            return bool(val)
        if target_type is list:
            if isinstance(val, str):
                return [item.strip() for item in val.split(",")]
            if isinstance(val, (list, tuple)):
                return list(val)
            raise ValueError(f"Cannot cast {val!r} to list")
        if target_type is str:
            return str(val)
        # Fallback: try to evaluate Python literal
        try:
            import ast
            return ast.literal_eval(val)
        except Exception:
            return val

    for key, val in list(values_dict.items()):
        # Skip non-string values
        if not isinstance(val, str):
            continue

        # First, try explicit type mapping if available
        if key in type_map:
            target_type = type_map[key]
            try:
                values_dict[key] = _cast_value(val, target_type)
                continue
            except Exception:
                # Fall back to heuristics if mapping fails
                pass

        # Heuristic casting
        lowered = val.lower()
        if lowered == "none":
            values_dict[key] = None
            continue
        if lowered in ("true", "false"):
            values_dict[key] = lowered == "true"
            continue
        # Try integer
        try:
            values_dict[key] = int(val)
            continue
        except ValueError:
            pass
        # Try float
        try:
            values_dict[key] = float(val)
            continue
        except ValueError:
            pass
        # Try list (comma separated)
        if "," in val:
            values_dict[key] = [item.strip() for item in val.split(",")]
            continue
        # Keep as string if nothing else matched
        values_dict[key] = val
    # No return value; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='_'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate input
    if not isinstance(plugin_dir, (str, os.PathLike)):
        raise TypeError(f"plugin_dir must be a string or PathLike object, got {type(plugin_dir).__name__}")
    plugin_dir = os.fspath(plugin_dir)
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory")

    # Determine spec file
    spec_files = [
        os.path.join(plugin_dir, "metadata.json"),
        os.path.join(plugin_dir, "plugin.json"),
        os.path.join(plugin_dir, "metadata.yaml"),
        os.path.join(plugin_dir, "plugin.yaml"),
        os.path.join(plugin_dir, "metadata.yml"),
        os.path.join(plugin_dir, "plugin.yml"),
    ]

    spec_path = None
    for path in spec_files:
        if os.path.isfile(path):
            spec_path = path
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of: {', '.join(os.path.basename(p) for p in spec_files)}")

    # Load spec
    try:
        if spec_path.lower().endswith(('.yaml', '.yml')):
            try:
                import yaml
            except ImportError as exc:
                raise ImportError("PyYAML is required to parse YAML plugin specs") from exc
            with open(spec_path, 'r', encoding='utf-8') as f:
                spec_data = yaml.safe_load(f)
        else:
            with open(spec_path, 'r', encoding='utf-8') as f:
                spec_data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec '{spec_path}': {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec '{spec_path}' does not contain a dictionary at the top level")

    # Flatten and return
    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        # Only set the variable if it is not already defined
        if not os.getenv('CONFIG_PATH'):
            # Default to a config.json file in the current working directory
            default_path = os.path.join(os.getcwd(), 'config.json')
            os.environ['CONFIG_PATH'] = default_path
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError for clarity
        raise RuntimeError(f"Unable to set CONFIG_PATH: {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate input types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")

    # Normalize root by stripping trailing path separators
    root = root.rstrip('/\\')
    if not root:
        raise ValueError("Root cannot be empty")

    # Ensure the path starts with the root
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")

    # Remove the root part
